local str = {}

--[[
    simple function to pipe string.rep and string.sub to templates. (does not have the 1,000 character limit that mediawiki has)
]]

function str.rep( frame )
	local repetitions = tonumber( frame.args[2] )
	if not repetitions then
		return str._error( 'function rep expects a number as second parameter, received "' .. ( frame.args[2] or '' ) .. '"' )
	end
	return string.rep( frame.args[1] or '', repetitions )
end

function str.sub( frame )
	local start = tonumber( frame.args[2] )
	local length = tonumber( frame.args[3] )

	if not start then
		return str._error( 'function sub expects a number as second parameter, received "' .. ( frame.args[2] or '' ) .. '"' )
	end

	if not length then
		return str._error( 'function sub expects a number as third parameter, received "' .. ( frame.args[3] or '' ) .. '"' )
	end

	return string.sub( frame.args[1] or '', start, length)
end

return str
